import {
  createControlPanel,
  createDisplay,
  createDateTime,
  createSystemProperties,
  createSoundProperties,
  createFolderOptions,
  createSimpleApplet,
} from './control-panel.js';
import {
  createSearch,
  createRestore,
  createBackup,
  createDiskCleanup,
  createScanDisk,
  createSysInfo,
  createRegistryEditor,
  createOnScreenKeyboard,
  createAddRemove,
  createScheduledTasks,
} from './utilities.js';
import { createHelp, createWelcome, createAbout } from './help.js';
export function registerSystem(registry) {
  for (const app of [
    {
      id: 'control',
      title: 'Control Panel',
      icon: 'control',
      commands: ['control.exe', 'control'],
      create: createControlPanel,
    },
    {
      id: 'display',
      title: 'Display Properties',
      icon: 'display',
      commands: ['desk.cpl'],
      create: createDisplay,
    },
    {
      id: 'date-time',
      title: 'Date/Time Properties',
      icon: 'clock',
      commands: ['timedate.cpl'],
      create: createDateTime,
    },
    {
      id: 'system',
      title: 'System Properties',
      icon: 'computer',
      commands: ['sysdm.cpl'],
      create: createSystemProperties,
    },
    {
      id: 'sound-properties',
      title: 'Sounds and Multimedia',
      icon: 'sound',
      commands: ['mmsys.cpl'],
      create: createSoundProperties,
    },
    {
      id: 'volume',
      title: 'Volume Control',
      icon: 'sound',
      commands: ['sndvol32', 'sndvol32.exe'],
      create: (sys) => createSoundProperties(sys, { volumeOnly: true }),
    },
    { id: 'folder-options', title: 'Folder Options', icon: 'folder', create: createFolderOptions },
    { id: 'search', title: 'Search', icon: 'search', commands: ['find'], create: createSearch },
    {
      id: 'restore',
      title: 'System Restore',
      icon: 'control',
      commands: ['rstrui', 'rstrui.exe'],
      create: createRestore,
      category: 'System Tools',
    },
    {
      id: 'backup',
      title: 'Backup',
      icon: 'floppy',
      commands: ['msbackup', 'msbackup.exe'],
      create: createBackup,
      category: 'System Tools',
    },
    {
      id: 'cleanup',
      title: 'Disk Cleanup',
      icon: 'disk',
      commands: ['cleanmgr', 'cleanmgr.exe'],
      create: createDiskCleanup,
      category: 'System Tools',
    },
    {
      id: 'scandisk',
      title: 'ScanDisk',
      icon: 'disk',
      commands: ['scandskw', 'scandskw.exe'],
      create: createScanDisk,
      category: 'System Tools',
    },
    {
      id: 'defrag',
      title: 'Disk Defragmenter',
      icon: 'disk',
      commands: ['defrag.exe'],
      create: (sys) => createScanDisk(sys, { defrag: true }),
      category: 'System Tools',
    },
    {
      id: 'sysinfo',
      title: 'System Information',
      icon: 'computer',
      commands: ['msinfo32', 'msinfo32.exe'],
      create: createSysInfo,
      category: 'System Tools',
    },
    {
      id: 'regedit',
      title: 'Registry Editor',
      icon: 'registry',
      commands: ['regedit.exe'],
      create: createRegistryEditor,
      category: 'System Tools',
    },
    {
      id: 'osk',
      title: 'On-Screen Keyboard',
      icon: 'keyboard',
      commands: ['osk.exe'],
      create: createOnScreenKeyboard,
    },
    {
      id: 'add-remove',
      title: 'Add/Remove Programs',
      icon: 'control',
      commands: ['appwiz.cpl'],
      create: createAddRemove,
    },
    {
      id: 'scheduled-tasks',
      title: 'Scheduled Tasks',
      icon: 'clock',
      commands: ['mstask'],
      create: createScheduledTasks,
      category: 'System Tools',
    },
    {
      id: 'help',
      title: 'Help and Support',
      icon: 'help',
      commands: ['helpctr', 'helpctr.exe'],
      create: createHelp,
    },
    {
      id: 'welcome',
      title: 'Welcome to Windows Me',
      icon: 'windows',
      commands: ['welcome.exe'],
      create: createWelcome,
    },
    {
      id: 'about',
      title: 'About Windows',
      icon: 'windows',
      commands: ['winver', 'winver.exe'],
      create: createAbout,
    },
    ...[
      'mouse',
      'keyboard',
      'regional',
      'accessibility',
      'power',
      'passwords',
      'fonts',
      'game-controllers',
      'printers',
    ].map((id) => ({
      id,
      title: id,
      icon: 'control',
      commands: id === 'mouse' ? ['main.cpl'] : [],
      create: (sys) => createSimpleApplet(sys, { id }),
    })),
  ])
    registry.register({ ...app, singleton: !['search', 'about'].includes(app.id) });
}
